 if(!Number.isSafeInteger(amount)||amount<0||typeof currency!=='string'||!supported.includes(currency))throw Error('Unsupported or invalid Stripe charge currency or amount');
 if((currency==='isk'||currency==='ugx')&&amount%100!==0)throw Error('Invalid Stripe special-currency amount');
 if(zero.includes(currency))return String(amount);
 const places=['bhd','jod','kwd','omr','tnd'].includes(currency)?3:2,digits=String(amount).padStart(places+1,'0');return digits.slice(0,-places)+'.'+digits.slice(-places);
}

